275	    /**
276	     * The owner's membership points. Start at 0, add 2 when an email is present, add 1 when
277	     * {@code namesakeCount} is 0, add 2 for a household of 3 or more members, and add 3 when tenure
278	     * exceeds 365 days, measured from {@code registrationDate} to the current date. Not persisted.
279	     */
280	    @Transient
281	    public Integer getMembershipPoints() {
282	        int points = 0;
283	        if (this.email != null && !this.email.isBlank()) {
284	            points += 2;
285	        }
286	        if (this.namesakeCount != null && this.namesakeCount == 0) {
287	            points += 1;
288	        }
289	        if (this.householdSize != null && this.householdSize >= 3) {
290	            points += 2;
291	        }
292	        if (this.registrationDate != null
293	                && java.time.temporal.ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now()) > 365) {
294	            points += 3;
295	        }
296	        return points;
297	    }
298	
299	    /**
300	     * The owner's membership level (1 to 4), derived from {@link #getMembershipPoints()}: level 1
301	     * for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more. Not persisted.
302	     */
303	    @Transient
304	    public Integer getMembershipLevel() {
305	        int points = getMembershipPoints();
306	        if (points <= 1) {
307	            return 1;
308	        }
309	        if (points <= 3) {
310	            return 2;
311	        }
312	        if (points <= 5) {
313	            return 3;
314	        }
315	        return 4;
316	    }
