327	    /**
328	     * A single Luhn check digit (0 to 9) computed over the digits contained in the
329	     * {@code customerCode}. Non-digit characters are ignored. Not persisted.
330	     */
331	    @Transient
332	    public Integer getCheckDigit() {
333	        String code = this.customerCode == null ? "" : this.customerCode;
334	        int sum = 0;
335	        boolean dbl = true;
336	        for (int i = code.length() - 1; i >= 0; i--) {
337	            char c = code.charAt(i);
338	            if (c < '0' || c > '9') {
339	                continue;
340	            }
341	            int d = c - '0';
342	            if (dbl) {
343	                d *= 2;
344	                if (d > 9) {
345	                    d -= 9;
346	                }
347	            }
348	            sum += d;
349	            dbl = !dbl;
350	        }
351	        return (10 - (sum % 10)) % 10;
352	    }
