394	     * @return true if pet name is already in use
395	     */
396	    public Pet getPet(String name, boolean ignoreNew) {
397	        name = name.toLowerCase();
398	        for (Pet pet : getPetsInternal()) {
399	            if (!ignoreNew || !pet.isNew()) {
400	                String compName = pet.getName();
401	                compName = compName.toLowerCase();
402	                if (compName.equals(name)) {
403	                    return pet;
404	                }
405	            }
406	        }
407	        return null;
408	    }
